/** Component faults vs instrumentation faults — the line in the incidence
 *  matrix. Everything below it is a sensor, not an engine. */
export const SENSOR_FAULTS: FaultId[] = [
  'map_sensor_drift',
  'egt_sensor_drift',
  'cht_sensor_drift',
  'lambda_sensor_drift',
];
